//! Lightweight game client code generation for the Rust shell.
//!
//! Emits the `src/bin/game.rs` entry point: the Dioxus window this shell
//! ships (`renderers/dioxus`) over the app's server.

/// Generate the `src/bin/game.rs` source for the generated application.
pub fn generate_game_bin() -> String {
    r#"//! Game client entry point.
//!
//! Generated by the Orbital Rust shell. Run with:
//!   cargo run --bin game
//!
//! The client communicates with the Orbital server (default
//! http://127.0.0.1:3030) using the closed-circuit event protocol.

use orbital_core::client::bridge::ServerBridge;
use orbital_core::client::http::SyncServerBridge;
use std::sync::Arc;

fn main() -> anyhow::Result<()> {
    let server_url = std::env::var("SERVER_URL").unwrap_or_else(|_| "http://127.0.0.1:3030".to_string());
    let schema = orbital_core::schema::parse_schema_file(std::path::Path::new("resolved.orb"))?;
    let title = schema.name.clone();
    orbital_client_dioxus::shell::mount(schema, Arc::new(SyncServerBridge::new(server_url)) as Arc<dyn ServerBridge>);
    orbital_client_dioxus::native::open_window(orbital_client_dioxus::styles::stylesheets(), &title);
    Ok(())
}
"#
    .to_string()
}
